"""Curated research inputs and reproducible expansion export. Run with the website root."""
import json, csv, sys
from pathlib import Path
root=Path(sys.argv[1]); dest=root/'Informatics/library-data'; dest.mkdir(parents=True,exist_ok=True)
rows=[]
def add(slug,title,journal,year,url,design,summary,role,scope,group,quality='Controlled mechanistic evidence',relevance='Direct mechanism',origin='Additional research',doi='',pmid='',score=1,blind='not-verified',extra=()):
 rows.append(dict(slug=slug,title=title,journal=journal,year=year,urls=[url,*extra],design=design,summary=summary,role=role,limitation=scope,group=group,quality=quality,relevance=relevance,origin=origin,doi=doi,pmid=pmid,score=score,blind=blind))
add('kouider2010','Cerebral bases of subliminal speech priming','NeuroImage',2010,'https://pubmed.ncbi.nlm.nih.gov/19715763/','Behavioural priming and fMRI; 16 participants','Masked, compressed spoken words influenced subsequent word processing. Repetition-related responses in temporal and insular regions occurred with prime identification near chance.','Direct evidence that lexical processing can occur without reportable word identification.','Short, tightly controlled primes; repetition suppression indexes altered processing, not a measured emotional or therapeutic response.','lead',origin='Gemini',doi='10.1016/j.neuroimage.2009.08.043',pmid='19715763',extra=('https://www.pallier.org/papers/Kouider.Pallier.subliminal.priming.fmri.2009.pdf','https://www.semanticscholar.org/paper/Cerebral-bases-of-subliminal-speech-priming-Kouider-Gardelle/b44d347fb2834f322613575801dac798e4698004'))
add('kouider2005','Subliminal speech priming','Psychological Science',2005,'https://pubmed.ncbi.nlm.nih.gov/16102064/','Controlled experiments with compressed and masked speech','Masked speech produced repetition priming, including effects across different voices. Evidence for semantic overlap was more limited.','Establishes a behavioural route from a masked acoustic signal to word-level representations.','Word identity, phonological processing and sentence meaning are distinct levels of processing.','lead',doi='10.1111/j.1467-9280.2005.01584.x',pmid='16102064')
add('yasmin2023','The effects of speech masking on neural tracking of acoustic and semantic features of natural speech','Neuropsychologia',2023,'https://pubmed.ncbi.nlm.nih.gov/37169066/','EEG during stories presented with competing speech','Acoustic and semantic tracking changed differently with masking. Semantic tracking remained measurable across several masking levels and weakened under the most severe masking.','Shows how speech meaning and timing can remain represented when competing sound obscures speech.','Participants attended to the stories; partially intelligible speech is distinct from objectively undetectable speech.','lead',origin='Gemini',doi='10.1016/j.neuropsychologia.2023.108584',pmid='37169066')
add('leonard2016','Perceptual restoration of masked speech in human cortex','Nature Communications',2016,'https://www.nature.com/articles/ncomms13619','Intracranial cortical recordings; five participants','Neural responses reflected the speech sounds listeners perceived when noise replaced parts of words. Context and prior neural activity helped explain restoration.','Demonstrates reconstruction of missing speech information using surviving acoustic cues and expectations.','The experiment replaced parts of speech; it did not remove all acoustic information from an entire message.','lead',doi='10.1038/ncomms13619')
add('herrmann2025','Enhanced neural speech tracking through noise indicates stochastic resonance in humans','eLife',2025,'https://elifesciences.org/articles/100830','Five EEG experiments; peer-reviewed version of record','Minimal background noise enhanced neural tracking of speech amplitude onsets across a series of experiments.','Identifies a testable mechanism through which some noise conditions enhance early speech tracking.','Speech remained intelligible and louder than the added noise. The result depends on signal-to-noise conditions and does not establish a universal mixing level.','lead',quality='Converging experimental evidence',origin='Gemini',doi='10.7554/eLife.100830.3')
add('song2020','Auditory neural tracking and lexical processing of speech in noise: Masker type, spatial location, and language experience','Journal of the Acoustical Society of America',2020,'https://pubmed.ncbi.nlm.nih.gov/32752786/','EEG; speech-in-noise experiments','Masker type, spatial separation and language experience influenced neural tracking and lexical processing of attended speech.','Explains why masking, listening conditions and learned language knowledge alter speech extraction.','The task involved attended sentences; it does not establish full comprehension at every masking level.','mechanisms',origin='Gemini',doi='10.1121/10.0001477',pmid='32752786')
add('gutschalk2008','Neural Correlates of Auditory Perceptual Awareness under Informational Masking','PLOS Biology',2008,'https://journals.plos.org/plosbiology/article?id=10.1371/journal.pbio.0060138','MEG; detected and undetected tones in competing sounds','Early auditory responses persisted for undetected tones, while later activity tracked perceptual awareness.','Separates sensory encoding from conscious access, a foundation for studying masked-language processing.','Tone detection establishes an auditory processing principle; linguistic decoding requires additional evidence.','mechanisms',origin='Gemini',doi='10.1371/journal.pbio.0060138',relevance='Associated auditory mechanism')
add('chen2025','Neural markers of speech processing during inattentional deafness','Cortex',2025,'https://pubmed.ncbi.nlm.nih.gov/41253014/','Two preregistered EEG experiments; 67 participants','Neural differences between words and pseudowords remained measurable when attention was occupied and participants failed to notice the speech.','Supports lexical processing outside focal attention and motivates tests during music listening.','Inattention and acoustic masking are different routes to reduced awareness. Task relevance affected processing.','mechanisms',doi='10.1016/j.cortex.2025.10.010',pmid='41253014',relevance='Associated lexical mechanism')
add('brown2023','Neurophysiological Evidence for Semantic Processing of Irrelevant Speech and Own-Name Detection in a Virtual Café','Journal of Neuroscience',2023,'https://pmc.ncbi.nlm.nih.gov/articles/PMC10324990/','EEG and skin conductance; 50 recruited participants','Unattended café speech elicited responses related to semantic violations and personally significant own-name information.','Connects unattended language, personal relevance and physiological measures.','Irrelevant speech was audible; own-name effects do not establish an effect for every familiar phrase.','mechanisms',doi='10.1523/JNEUROSCI.1731-22.2023',pmid='37336758',relevance='Associated semantic and salience mechanism')
add('brooks2012','Exposure to subliminal arousing stimuli induces robust activation in the amygdala, hippocampus, anterior cingulate, insular cortex and primary visual cortex: a systematic meta-analysis of fMRI studies','NeuroImage',2012,'https://pubmed.ncbi.nlm.nih.gov/22001789/','Systematic meta-analysis of fMRI studies','Subliminal emotional stimuli recruited networks involved in salience and emotion; evidence differed by stimulus type, with prominent facial-stimulus findings.','Provides a general bridge between reduced awareness and emotion-related neural responses.','Much of this literature is visual. Its contribution is a cross-modal hypothesis about emotional processing.','mechanisms',quality='Evidence synthesis; indirect modality',relevance='Associated emotional mechanism',origin='Gemini',doi='10.1016/j.neuroimage.2011.09.077',pmid='22001789')
add('hung2020','Task-induced attention load guides and gates unconscious semantic interference','Nature Communications',2020,'https://www.nature.com/articles/s41467-020-15439-x','Controlled visual masking experiments','Attentional load modulated unconscious semantic interference.','Helps formulate when limited attention may permit or constrain implicit meaning processing.','Visual-word experiments; transfer to auditory music masking remains a research question.','mechanisms',relevance='Associated attention mechanism',doi='10.1038/s41467-020-15439-x')
add('subcortical2024','The effect of speech masking on the human subcortical response to continuous speech','eNeuro',2025,'https://pubmed.ncbi.nlm.nih.gov/40127932/','Auditory brainstem responses to competing speech; 25 participants','Brainstem responses to individual speech streams remained measurable in mixtures. More competing talkers reduced response amplitude and increased latency.','Extends the evidence map to early auditory encoding and signal degradation.','Published in 2025 after the indexed preprint. Brainstem encoding is an early processing stage, distinct from understanding meaning.','mechanisms',quality='Controlled electrophysiological evidence',relevance='Associated auditory mechanism',pmid='40127932',doi='10.1523/ENEURO.0561-24.2025',extra=('https://pubmed.ncbi.nlm.nih.gov/39713441/',))
add('nowak2020','Effect of therapeutic suggestions during general anaesthesia on postoperative pain and opioid use: multicentre randomised controlled trial','BMJ',2020,'https://pmc.ncbi.nlm.nih.gov/articles/PMC7726311/','Multicentre double-blind randomized controlled trial; 385 analysed','Music with therapeutic suggestions during general anaesthesia reduced postoperative opioid use relative to a blank recording. Median morphine-equivalent use was 4.0 versus 5.3 mg.','High-quality clinical evidence that externally delivered audio during an unconscious state may influence later physiological or behavioural outcomes.','The intervention combined music and suggestions. Anaesthesia differs from awake masking, and the design does not isolate the spoken component.','anaesthesia',quality='Multicentre double-blind RCT',relevance='Associated clinical evidence',doi='10.1136/bmj.m4284',pmid='33303476',score=3,blind='double')
add('rosendahl2016','Efficacy of therapeutic suggestions under general anesthesia: a systematic review and meta-analysis of randomized controlled trials','BMC Anesthesiology',2016,'https://pmc.ncbi.nlm.nih.gov/articles/PMC5178078/','Systematic review and meta-analysis; 32 randomized trials, 2,102 patients','Pooled results found small effects for medication use and recovery, with little or no overall effect for pain and distress.','Places anaesthesia audio studies in a larger evidence base and identifies outcomes with stronger or weaker signals.','Trials varied in interventions and methods. A review of trials is not itself a double-blind trial.','anaesthesia',quality='Systematic review of randomized trials',relevance='Associated clinical synthesis',doi='10.1186/s12871-016-0292-0',pmid='28007033')
add('katlowitz2026','Plasticity and language in the anaesthetized human hippocampus','Nature',2026,'https://www.nature.com/articles/s41586-026-10448-0','Human hippocampal single-unit recordings during anaesthesia','Hippocampal recordings during propofol anaesthesia showed responses to language features and learning-related patterns. Natural-speech analyses included four participants and 375 units.','Adds direct human neuronal evidence that language-related processing can persist during an unconscious state.','Small neurosurgical sample; intact speech under anaesthesia is distinct from speech masked beneath music.','anaesthesia',quality='Direct human neuronal recordings; small sample',relevance='Associated language mechanism',doi='10.1038/s41586-026-10448-0',extra=('https://pmc.ncbi.nlm.nih.gov/articles/PMC13275293/',))
add('greenwald1991','Double-Blind Tests of Subliminal Self-Help Audiotapes','Psychological Science',1991,'https://www.psychologicalscience.org/journals/psychological-science/j.1467-9280.1991.tb00112.x/','Double-blind randomized experiments; 237 participants across three replications','A month of use produced no content-specific improvement in the targeted memory or self-esteem measures. Perceived improvement followed tape labels.','A strong design reference for separating message effects, expectations and general listening effects.','These null outcomes constrain those tested self-help recordings; they do not negate auditory encoding or word priming.','outcomes',quality='Double-blind randomized evidence',relevance='Direct masked-audio outcome test',doi='10.1111/j.1467-9280.1991.tb00112.x',score=3,blind='double')
add('aarabi2023','Effect of Subliminal Auditory Stimulation on Components of Auditory Late Responses and Functional Magnetic Resonance Imaging Data in Adults with Normal Hearing','Auditory and Vestibular Research',2023,'https://publish.kne-publishing.com/index.php/AVR/article/view/12934','Small controlled exposure study; EEG and fMRI','Words masked beneath instrumental music were presented repeatedly over ten days. The study reported changes in auditory evoked-potential amplitudes and some fMRI responses.','A close delivery match for testing whether repeated speech beneath music can alter subsequent neural responses.','Small groups and incompletely clear allocation and participant flow. Responses to audible test words were measured after exposure; structural brain change and emotional benefit were not established.','outcomes',quality='Exploratory controlled study',relevance='Direct delivery match',origin='Gemini',doi='10.18502/avr.v32i3.12934',extra=('https://publish.kne-publishing.com/index.php/AVR/article/download/12934/12173/14421',))
add('chakalis1992','Positive effects of subliminal stimulation on memory','Perceptual and Motor Skills',1992,'https://pubmed.ncbi.nlm.nih.gov/1608733/','Randomized three-group study; 60 participants','The subliminal music group improved name recall after a short exposure; silence and music comparison groups were also included.','An early positive behavioural signal linking masked verbal stimulation with memory performance.','The abstract reports within-group improvement; a verified between-group effect and blinding details are needed for stronger inference.','outcomes',quality='Small randomized study; limited reporting',relevance='Direct masked-audio outcome test',doi='10.2466/pms.1992.74.3.956',pmid='1608733',score=2)
add('egermann2006','Is there an effect of subliminal messages in music on choice behavior?','Journal of Articles in Support of the Null Hypothesis',2006,'https://www.jasnh.com/pdf/Vol4-No2-article1.pdf','Blinded music-listening experiments; adults and children','Messages embedded in music did not reliably change the tested word or drink choices.','Tests a specific step from masked messages to overt decisions and helps select sensitive endpoints.','Choice outcomes differ from neural encoding, autonomic response and longer-term learning.','outcomes',quality='Controlled behavioural experiments',relevance='Direct masked-music outcome test')
add('borgeat1989','Psychophysiological responses to subliminal auditory suggestions for activation','Perceptual and Motor Skills',1989,'https://pubmed.ncbi.nlm.nih.gov/2608414/','Small psychophysiological experiment; 20 participants','Masked activating suggestions were associated with a heart-rate response during a stress task; skin conductance did not show the same effect.','An early physiological link for testing autonomic responses to masked verbal content.','Small, older study; heart rate is not heart-rate variability and the measures are not interchangeable.','outcomes',quality='Exploratory physiological experiment',relevance='Direct masked-audio physiology',doi='10.1177/00315125890693-145',pmid='2608414')
add('funk2022','Subliminal Priming with Positive Auditory Stimuli Significantly Improves Self-Esteem and Emotional Well-Being','European Journal of Medical and Health Sciences',2022,'https://www.ej-med.org/index.php/ejmed/article/view/1328','Retrospective service study; 535 adults and children','Self-reported wellbeing improved during a programme of repeated positive auditory sessions.','Provides an observational signal and candidate psychological outcomes for prospective controlled work.','No randomized comparator; provider involvement and self-report limit causal attribution. The publication title is retained verbatim.','outcomes',quality='Observational service data',relevance='Direct intervention context',origin='Gemini',doi='10.24018/ejmed.2022.4.6.1328')
add('khalilpour2025','Effectiveness of subliminal audio messages on depression and anxiety in women with hypertension: a quasi-experimental study','Social Determinants of Health',2025,'https://journals.sbmu.ac.ir/sdh/article/view/48724','Author-described quasi-experimental study; 30 women','The report describes reduced anxiety and depression after six weeks of subliminal-audio sessions.','Adds a preliminary clinical signal and a population for further replication.','Purposive recruitment; allocation, blinding and comparator details require full methodological confirmation. No verified double-blind classification.','outcomes',quality='Preliminary clinical report',relevance='Direct intervention context',doi='10.22037/sdh.v11i1.48724')
add('vieira2025','Positive Auditory Stimuli and Its Effects on PTSD: A Case Study on Police Officers','European Journal of Medical and Health Sciences',2025,'https://eu-opensci.org/index.php/ejmed/article/download/42290/10924/53575','Case series; three police officers','The report describes self-reported changes during a positive-auditory-stimulation programme.','Descriptive material for generating outcome questions and documenting intervention delivery.','Three uncontrolled cases, provider involvement and subjective outcomes; no causal estimate.','outcomes',quality='Case series',relevance='Direct intervention context',doi='10.24018/ejmed.2025.7.5.2290')
add('motor2026','Subliminal Priming Effects on Motor and Cognitive Performance: Pilot Evidence With Implications for Neurorehabilitation','PubMed / PMC publication record',2026,'https://pmc.ncbi.nlm.nih.gov/articles/PMC13340606/','Single-blind randomized pilot; 30 participants, three priming modalities','The pilot compared priming modalities and reported selective motor and cognitive findings.','Extends the outcome map beyond self-report and suggests objective performance measures.','Small groups, multiple outcomes and no sham group; selective findings need replication.','outcomes',quality='Exploratory randomized pilot',relevance='Associated priming outcomes',pmid='42415977',score=2,blind='single')
add('gao2019','The neurophysiological correlates of religious chanting','Scientific Reports',2019,'https://www.nature.com/articles/s41598-019-40200-w','EEG and ECG in experienced practitioners; supplementary single-person fMRI','Silent internal religious chanting was associated with neural and cardiac differences across comparison conditions.','Helps frame the role of learned meaning, practice and personally meaningful mantra associations.','Participants actively recited internally. This is silent mental mantra, a different intervention from an external masked recording.','context',quality='Small experimental study',relevance='Meaningful-mantra context',doi='10.1038/s41598-019-40200-w')
add('gao2017','Repetitive Religious Chanting Modulates the Late-Stage Brain Response to Fear- and Stress-Provoking Pictures','Frontiers in Psychology',2017,'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2016.02055/full','EEG; active chanting and emotional pictures','Religious chanting modulated later brain responses to negative pictures.','Supports testing whether learned associations and repetition alter later emotional appraisal.','Active chanting; overlap with related research samples may limit independence. Early and late responses differed.','context',quality='Experimental EEG evidence',relevance='Emotion and mantra context',doi='10.3389/fpsyg.2016.02055',pmid='28119651')
add('bernardi2001','Effect of rosary prayer and yoga mantras on autonomic cardiovascular rhythms: comparative study','BMJ',2001,'https://pmc.ncbi.nlm.nih.gov/articles/PMC61046/','Comparative physiological study; 23 participants','Recitation slowed breathing towards six breaths per minute and increased cardiovascular rhythm coordination and baroreflex sensitivity.','Identifies respiration as an important pathway and measurement variable in mantra-related autonomic effects.','Active recitation directly changes breathing. An external masked track may not reproduce this respiratory behaviour.','context',quality='Controlled physiological comparison',relevance='Autonomic mechanism context',doi='10.1136/bmj.323.7327.1446',pmid='11751348')
add('black2013','Yogic meditation reverses NF-κB and IRF-related transcriptome dynamics in leukocytes of family dementia caregivers in a randomized controlled trial','Psychoneuroendocrinology',2013,'https://pubmed.ncbi.nlm.nih.gov/22795617/','Randomized active-meditation versus music study; 45 randomized, 39 completed','Eight weeks of Kirtan Kriya were associated with differences in leukocyte gene-expression patterns and inferred transcription-factor activity.','Provides a molecular endpoint precedent for a future controlled study of stress regulation.','Active multicomponent meditation, not masked audio. Peripheral gene expression does not establish a masked-language mechanism. Linked to the Lavretsky caregiver trial.','context',quality='Small randomized trial',relevance='Molecular endpoint context',pmid='22795617',score=2)
add('lavretsky2013','A pilot study of yogic meditation for family dementia caregivers with depressive symptoms: effects on mental health, cognition, and telomerase activity','International Journal of Geriatric Psychiatry',2013,'https://pubmed.ncbi.nlm.nih.gov/22407663/','Randomized caregiver meditation pilot; 39 completers','The active-meditation comparison assessed mood, cognition and telomerase activity after eight weeks.','Provides a precedent for combining psychological and cellular measurements.','Related to the Black transcriptome report; these publications do not count as independent trials.','context',quality='Small randomized trial',relevance='Cellular endpoint context',pmid='22407663',score=2)
add('wahbeh2026','Digital meditation at scale: a randomized citizen science trial comparing four meditation practices','BMC Psychology',2026,'https://link.springer.com/article/10.1186/s40359-026-05869-5','Randomized digital trial; 1,211 participants assigned to meditation or music conditions','Four weeks of practice were assessed with subjective, EEG and HRV measures. The preregistered primary findings did not survive multiplicity correction.','A useful design and feasibility reference for digital delivery, active controls, HRV and EEG.','Active practices, including mantra, differ from masked playback; substantial attrition complicates interpretation.','context',quality='Large randomized study; attrition limitations',relevance='Digital evaluation context',doi='10.1186/s40359-026-05869-5',score=2)
add('vickhoff2013','Music structure determines heart rate variability of singers','Frontiers in Psychology',2013,'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2013.00334/full','Physiological experiments during singing','Musical phrasing and breathing patterns organised heart-rate variability during singing and mantra-like phrases.','Shows why respiration and musical structure need measurement alongside any spoken-message manipulation.','Active vocalisation and coordinated breathing; this mechanism is not automatically present during passive masked listening.','context',quality='Experimental physiology',relevance='Music and breathing context',doi='10.3389/fpsyg.2013.00334')
add('meditation2015','Cardiovascular and nervous system changes during meditation','Frontiers in Human Neuroscience',2015,'https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2015.00145/full','Physiological study during active meditation','Cardiovascular and neural measures changed during meditation; HRV measures did not all move in the same direction.','Encourages endpoint-specific interpretation of autonomic effects.','Different HRV indices reflect different processes and depend on respiration, timing and experience.','context',quality='Experimental physiology',relevance='Autonomic measurement context',doi='10.3389/fnhum.2015.00145')
add('beats2025','Beating stress: music with monaural beats reduces anxiety and improves mood in a non-clinical population','PMC publication record',2025,'https://pmc.ncbi.nlm.nih.gov/articles/PMC12213757/','Single-blind randomized sound study; 308 participants','The trial compared music with monaural beats, beats and pure-tone conditions on anxiety and mood.','Documents potential effects from the carrier audio itself, informing controls for masked-language research.','No music-only arm; nonlinguistic beats are distinct from verbal messages.','context',quality='Randomized sound comparison',relevance='Carrier-audio control context',score=2,blind='single')
add('stress2017','Inducing unconscious stress: Cardiovascular activity in response to subliminal presentation of threatening and neutral words','Psychophysiology',2017,'https://pubmed.ncbi.nlm.nih.gov/28497544/','Randomized subliminal visual-word experiment; 116 participants','Threatening versus neutral masked words increased total peripheral resistance significantly. Mean arterial pressure and HRV followed the predicted directions without statistically significant differences.','Indexes a route for examining semantic content and autonomic measures across modalities.','Visual presentation; the cardiovascular endpoints differed in statistical support. Transfer to auditory masking remains a research question.','context',quality='Randomized physiological experiment',relevance='Cross-modal autonomic hypothesis',doi='10.1111/psyp.12891',pmid='28497544')
